er((sc.region)) ,lower((sc.brand)) )) as Postage_Customer, safe_divide(ifnull(mc_ppc.Spend,0) , count(*) OVER (PARTITION BY coalesce(order_date,mc_ppc.date,dsp.date) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel,dsp.Channel)) ,lower(coalesce(sc.region,mc_ppc.region,dsp.region)) ,lower(coalesce(sc.brand,mc_ppc.brand)) )) as Spend, safe_divide(ifnull(mc_ppc.Conversion_Value,0) , count(*) OVER (PARTITION BY coalesce(order_date,mc_ppc.date,dsp.date) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel,dsp.Channel)) ,lower(coalesce(sc.region,mc_ppc.region,dsp.region)) ,lower(coalesce(sc.brand,mc_ppc.brand)) )) as Conversion_Value, safe_divide(ifnull(dsp.Dsp_Spend,0) , count(*) OVER (PARTITION BY coalesce(order_date,dsp.date,mc_ppc.date) ,lower(coalesce(sc.region,dsp.region,mc_ppc.region)) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel,dsp.Channel)) )) as Dsp_Spend from (select * from MAPLEMONK.CC_sales_consolidated where Order_Date_Flag = 1)SC left join ( select cast(paid_date as string) as order_date1 ,region ,brand ,marketplace as channel1 ,sum(case when ifnull(shipping_site_id,12333) != 29 then ifnull(shipping_cost_amz,0) else 0 end) Postage_Customer from maplemonk.website_marketplace_fact_items group by 1,2,3,4 )sc1 on cast(sc1.order_date1 as date) = cast(sc.order_date as date) and lower(sc1.channel1) = lower(sc.marketplace) and lower(sc1.region) = lower(sc.region) and lower(sc1.brand) = lower(sc.brand) full outer join ( select case when lower(channel) like any (\'%google%\',\'%bing%\') then \'PPC\' when lower(channel) like any (\'%SEO%\') then \'SEO\' when lower(channel) like any (\'%facebook%\') then \'SOCIAL MEDIA\' when lower(channel) like any (\'%affiliate%\') then \'AFFILIATES\' else channel end as Channel ,date ,region ,brand ,sum(ifnull(spend,0)) Spend ,sum(ifnull(Conversion_Value,0)) as Conversion_Value from `MAPLEMONK.CC_MARKETING_CONSOLIDATED` group by 1,2,3,4 )mc_ppc on cast(mc_ppc.date as date) = cast(sc.order_date as date) and lower(mc_ppc.channel) = lower(sc.channel) and 